bool cacheEvicts() {
    AssetCache cache;
    for (int i = 1; i <= 5; ++i) cache.insert(i);
    return !cache.contains(1) && cache.contains(5) && cache.capacity() == 4;
}

bool eventMatchesLayout() {
    EventBus events; UILayer ui; RenderEngine engine(events, ui);
    engine.resize(Size{0, 300});
    return events.count() == 1 && events.lastSize().width == ui.bounds().width &&
           events.lastSize().height == ui.bounds().height;
}

bool layoutClamps() {
    LayoutEngine layout;
    Rect bounds = layout.resolve(Size{-9, 9000});
    return bounds.width == 1 && bounds.height == 8192;
}

bool negativeResize() {
    EventBus events; UILayer ui; RenderEngine engine(events, ui);
    engine.resize(Size{-100, -5});
    return engine.viewport().width == 1 && engine.viewport().height == 1 &&
           ui.bounds().height == 1 && events.lastSize().height == 1;
}

bool nominalResize() {
    EventBus events; UILayer ui; RenderEngine engine(events, ui);
    WindowController window(engine);
    window.onSizeChanged(1280, 720);
    return engine.viewport().width == 1280 && ui.bounds().height == 720 &&
           events.count() == 1 && events.lastSize().height == 720;
}

bool oversizeResize() {
    EventBus events; UILayer ui; RenderEngine engine(events, ui);
    engine.resize(Size{9000, 12000});
    return engine.viewport().width == 8192 && engine.viewport().height == 8192 &&
           ui.bounds().width == 8192 && events.lastSize().height == 8192;
}

bool repeatedResize() {
    EventBus events; UILayer ui; RenderEngine engine(events, ui);
    engine.resize(Size{100, 200});
    engine.resize(Size{300, 400});
    return events.count() == 2 && engine.viewport().width == 300 &&
           ui.bounds().height == 400 && events.lastSize().width == 300;
}

bool zeroResize() {
    EventBus events; UILayer ui; RenderEngine engine(events, ui);
    engine.resize(Size{0, 0});
    return engine.viewport().width == 1 && engine.viewport().height == 1 &&
           ui.bounds().width == 1 && events.lastSize().width == 1;
}

bool AssetCache::contains(int id) const {
    for (int i = 0; i < capacity(); ++i) {
        if (ids_[i] == id) return true;
    }
    return false;
}

void AssetCache::insert(int id) {
    if (contains(id)) return;
    ids_[next_] = id;
    next_ = (next_ + 1) % capacity();
}

void EventBus::publish(const ViewportChanged& event) {
    last_ = event.size;
    ++count_;
}

int Geometry::clampDimension(int value) {
    if (value < 1) return 1;
    if (value > 8192) return 8192;
    return value;
}

float Geometry::clampDimension(float value) {
    if (value < 1.0f) return 1.0f;
    if (value > 8192.0f) return 8192.0f;
    return value;
}

bool Geometry::contains(const Rect& bounds, int x, int y) {
    return x >= bounds.x && y >= bounds.y &&
           x < bounds.x + bounds.width && y < bounds.y + bounds.height;
}

Rect LayoutEngine::resolve(Size available) const {
    return Rect{0, 0, Geometry::clampDimension(available.width),
                      Geometry::clampDimension(available.height)};
}

void RenderEngine::resize(Size requested) {
    // Existing implementation: the UI clamps, but viewport and event do not.
    viewport_ = requested;
    ui_.relayout(requested);
    events_.publish(ViewportChanged{viewport_});
}

void UILayer::relayout(Size available) {
    root_ = layout_.resolve(available);
}

void WindowController::onSizeChanged(int width, int height) {
    engine_.resize(Size{width, height});
}

